<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';$user=require_role('volunteer');
require_once __DIR__.'/../includes/volunteer_tasks.php';$id=donor_donation_id();
try {$task=volunteer_task($id,(int)$user['id']);}catch (PDOException $exception) {error_log('Volunteer detail failed. Code: '.$exception->getCode());donation_load_error();}
if (!$task) {http_response_code(404);exit('Collection task not found.');}
$donationStatus=donation_display_status($task);
$finished=volunteer_task_finished($task);
$closed=$task['task_status']==='cancelled' || $task['request_status']!=='approved' || in_array($donationStatus,['cancelled','expired'],true);
$nextAction=volunteer_next_action($task);$success=$_SESSION['task_update_success']??null;unset($_SESSION['task_update_success']);
$actionLabels=['accept'=>'Accept task','collect'=>'Mark collected','deliver'=>'Mark delivered'];
$confirmLabels=['accept'=>'I accept responsibility for this collection and delivery.',
    'collect'=>'I have collected this food from the donor.',
    'deliver'=>'I have delivered this food to the receiving organization.'];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Collection task | <?= e(APP_NAME) ?></title><link rel="stylesheet" href="<?= e(app_url('assets/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= e(app_url('assets/css/style.css')) ?>"></head><body>
<?php $navigationUser=$user;require __DIR__.'/../includes/header.php'; ?><main class="container py-5" id="main-content"><div class="row g-4"><?php $volunteerPage=$finished?'history':'tasks';require __DIR__.'/../includes/volunteer_sidebar.php'; ?>
<section class="col-lg-9" aria-labelledby="task-heading"><div class="dashboard-welcome mb-4"><a class="home-link" href="<?= e(app_url($finished?'volunteer/history.php':'volunteer/tasks.php')) ?>">&larr; <?= $finished?'Completed task history':'My collection tasks' ?></a><h1 class="h2 mt-3" id="task-heading"><?= e($task['food_name']) ?></h1><div class="dashboard-meta"><span>Task: <?= status_badge($task['task_status']) ?></span><span>Donation: <?= status_badge($donationStatus) ?></span></div></div>
<?php if ($closed): ?><div class="alert alert-warning" role="status">This collection is closed or no longer eligible. Contact the administrator before travelling.</div><?php endif; ?>
<?php if (is_array($success) && ($success['id']??null)===$id): ?><div class="alert alert-success" role="status"><?= e($success['message']) ?></div><?php endif; ?>
<?php if ($nextAction!==null): ?><section class="account-card mb-4" aria-labelledby="update-heading"><h2 class="h5" id="update-heading"><?= e($actionLabels[$nextAction]) ?></h2><form method="post" action="<?= e(app_url('volunteer/update_task.php?id='.$id)) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= e($nextAction) ?>"><div class="form-check my-3"><input class="form-check-input" id="confirm-update" name="confirm_update" value="yes" type="checkbox" required><label class="form-check-label" for="confirm-update"><?= e($confirmLabels[$nextAction]) ?></label></div><button class="btn btn-community"><?= e($actionLabels[$nextAction]) ?></button></form></section>
<?php elseif ($task['task_status']==='delivered' && $task['status']==='delivered' && !$closed): ?><div class="alert alert-info" role="status">Delivery is recorded. Awaiting the organization's receipt confirmation.</div><?php endif; ?>
<section class="account-card mb-4"><h2 class="h5">Food and collection window</h2><p class="donation-description"><?= e($task['description']) ?></p><dl class="row account-details mb-0"><dt class="col-sm-4">Quantity</dt><dd class="col-sm-8"><?= e(rtrim(rtrim($task['quantity'],'0'),'.').' '.$task['quantity_unit']) ?></dd><dt class="col-sm-4">Available from</dt><dd class="col-sm-8"><?= e(dashboard_date($task['available_at'])) ?></dd><dt class="col-sm-4">Collect by</dt><dd class="col-sm-8"><?= e(dashboard_date($task['deadline_at'])) ?></dd></dl></section>
<?php if (!$closed): ?><section class="account-card mb-4"><h2 class="h5">Pickup details</h2><dl class="row account-details mt-3 mb-0"><dt class="col-sm-4">Donor</dt><dd class="col-sm-8"><?= e($task['donor_name']) ?></dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8"><?= e($task['donor_phone']) ?></dd><dt class="col-sm-4">Pickup location</dt><dd class="col-sm-8 donation-description"><?= e($task['pickup_location']) ?></dd></dl></section>
<section class="account-card mb-4"><h2 class="h5">Delivery details</h2><dl class="row account-details mt-3 mb-0"><dt class="col-sm-4">Organization</dt><dd class="col-sm-8"><?= e($task['organization_name']) ?></dd><dt class="col-sm-4">Contact person</dt><dd class="col-sm-8"><?= e($task['recipient_name']) ?></dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8"><?= e($task['recipient_phone']) ?></dd><dt class="col-sm-4">Delivery address</dt><dd class="col-sm-8 donation-description"><?= e($task['delivery_address']) ?></dd><dt class="col-sm-4">Request message</dt><dd class="col-sm-8 donation-description"><?= e($task['message']??'No message provided.') ?></dd></dl></section><?php endif; ?>
<section class="account-card"><h2 class="h5 mb-4">Recorded progress</h2><ol class="request-timeline"><?php foreach ([['Assigned',$task['assigned_at']],['Accepted',$task['accepted_at']],['Collected',$task['collected_at']],['Delivered',$task['delivered_at']],['Receipt confirmed',$task['status']==='completed'?$task['completed_at']:null]] as [$label,$time]): ?><li class="<?= $time!==null?'is-recorded':'' ?>"><span class="timeline-dot" aria-hidden="true"></span><div><strong><?= e($label) ?></strong><span><?= $time!==null?e(dashboard_date($time)):'Not recorded yet' ?></span></div></li><?php endforeach; ?></ol><p class="form-text mt-3 mb-0">Times use Sri Lanka time.</p></section>
</section></div></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
